function clearHighlights(){
  document.querySelectorAll('[data-hl]').forEach(function(el){
    for(var c=0;c<el.children.length;c++){el.children[c].style.outline="";el.children[c].style.outlineOffset=""}
    el.removeAttribute('data-hl')
  })
}
function highlightPlayable(player){
  clearHighlights();
  if(!gameInstance){console.log("HL: pas de jeu");return}
  var b=gameInstance.board;
  var prefix=player===gameInstance.player?'b':'o';
  var cf=[1,16][player],ef=[2,32][player],tf=4|64;
  var count=0;
  for(var bid=0;bid<21;bid++){
    if(b.used[bid+player*21])continue;
    var found=false;
    for(var x=0;x<14&&!found;x++)for(var y=0;y<14&&!found;y++)for(var d=0;d<8&&!found;d++){
      var mv=new f(x,y,bid<<3|d);var co=mv.coords();var ok=true,touch=false;
      for(var i=0;i<co.length;i++){var cx=co[i].x,cy=co[i].y;
        if(cx<0||cx>=14||cy<0||cy>=14){ok=false;break}
        var cell=b.square[cy][cx];
        if(cell&tf||(cell&ef)){ok=false;break}
        if(cell&cf)touch=true
      }
      if(ok&&touch)found=true
    }
    if(found){
      var el=document.getElementById(prefix+bid);
      if(el){
        el.setAttribute('data-hl','1');
        for(var c=0;c<el.children.length;c++){
          el.children[c].style.outline="2px solid #0f0";
          el.children[c].style.outlineOffset="1px"
        }
        count++
      }
    }
  }
  console.log("HL: "+count+" pieces jouables pour player "+player+" (prefix="+prefix+")")
}
var adviceWorker=null;
function giveAdvice(level){
  console.log("ADV: giveAdvice level="+level);
  if(!gameInstance){console.log("ADV: pas de jeu");return}
  var msg=document.getElementById("message");
  msg.innerHTML="Calcul du conseil...";msg.style.visibility="visible";
  if(!adviceWorker){
    console.log("ADV: creation worker");
    adviceWorker=new Worker("hm5move.js");
    adviceWorker.addEventListener("message",function(e){
      console.log("ADV: reponse worker="+JSON.stringify(e.data));
      var move=e.data.move||"";
      if(window.diagonalMode)move=transformMove(move);
      console.log("ADV: move apres transform="+JSON.stringify(move));
      var m=new f(move);
      if(move.indexOf("XXXX")>=0||move.length!==4||m.blockId()<0||m.blockId()>=21){
        console.log("ADV: move invalide");
        msg.innerHTML="Aucun conseil disponible";msg.style.visibility="visible";
        setTimeout(function(){msg.style.visibility="hidden"},3000);return
      }
      var coords=m.coords();var boardEl=document.getElementById("board");var adviceEls=[];
      for(var ci=0;ci<coords.length;ci++){
        var cell=document.createElement("div");
        cell.setAttribute("style","position:absolute;left:"+coords[ci].x*37+"px;top:"+coords[ci].y*37+"px;width:37px;height:37px;border:3px solid black;box-sizing:border-box;z-index:5;pointer-events:none;");
        boardEl.appendChild(cell);adviceEls.push(cell)
      }
      var el=document.getElementById("b"+m.blockId());
      if(el){el.classList.add("advice-highlight");setTimeout(function(){el.classList.remove("advice-highlight")},2000)}
      setTimeout(function(){for(var ci=0;ci<adviceEls.length;ci++){adviceEls[ci].remove()}msg.style.visibility="hidden"},2000);
      msg.innerHTML="Conseil sur la grille";msg.style.visibility="visible"
    });
    console.log("ADV: worker cree");
  }
  var path=gameInstance.board.getPath();
  if(window.diagonalMode)path=transformPath(path);
  console.log("ADV: envoi path="+path+" level="+level);
  adviceWorker.postMessage({path:path,level:level})
}
try{document.getElementById("hlPlayer").addEventListener("click",function(){console.log("HL player click");if(gameInstance)highlightPlayable(gameInstance.player);else console.log("pas de jeu")})}catch(e){console.log("err hlPlayer: "+e)}
try{document.getElementById("hlOpp").addEventListener("click",function(){console.log("HL opp click");if(gameInstance)highlightPlayable(1-gameInstance.player);else console.log("pas de jeu")})}catch(e){console.log("err hlOpp: "+e)}
try{document.getElementById("adv1").addEventListener("click",function(){console.log("ADV1 click");giveAdvice(1)})}catch(e){console.log("err adv1: "+e)}
try{document.getElementById("adv10").addEventListener("click",function(){console.log("ADV10 click");giveAdvice(2)})}catch(e){console.log("err adv10: "+e)}
try{document.getElementById("adv30").addEventListener("click",function(){console.log("ADV30 click");giveAdvice(3)})}catch(e){console.log("err adv30: "+e)}


function numberMoveOnBoard(move,num){
  var co=move.coords();var be=document.getElementById("board");
  var cx=0,cy=0;
  for(var i=0;i<co.length;i++){cx+=co[i].x;cy+=co[i].y}
  cx=cx/co.length;cy=cy/co.length;
  var best=0,bd=99;
  for(var i=0;i<co.length;i++){var d=Math.abs(co[i].x-cx)+Math.abs(co[i].y-cy);if(d<bd){bd=d;best=i}}
  var t=document.createElement("div");
  t.setAttribute("style","position:absolute;left:"+(co[best].x*37+6)+"px;top:"+(co[best].y*37+1)+"px;font-size:22px;font-weight:bold;color:white;text-shadow:1px 1px 3px black,1px 1px 3px black,1px 1px 3px black;z-index:15;pointer-events:none;");
  t.textContent=num;be.appendChild(t)
}

